import java.util.ArrayList;

public class PrefixSumsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<Integer> nums = new ArrayList<>(java.util.List.of(3, 1, 4));
        try {
            check("runningTotals([3, 1, 4])", "[3, 4, 8]", String.valueOf(PrefixSums.runningTotals(nums)));
            check("original list unchanged", "[3, 1, 4]", nums.toString());
            check("single element", "[5]", String.valueOf(PrefixSums.runningTotals(new ArrayList<>(java.util.List.of(5)))));
            check("empty list", "[]", String.valueOf(PrefixSums.runningTotals(new ArrayList<>())));
            check("negative numbers", "[10, 6, 7]", String.valueOf(PrefixSums.runningTotals(new ArrayList<>(java.util.List.of(10, -4, 1)))));
            check("zeros stay flat", "[2, 2, 2]", String.valueOf(PrefixSums.runningTotals(new ArrayList<>(java.util.List.of(2, 0, 0)))));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

