import java.util.ArrayList;

public class PrefixSums {

    public static ArrayList<Integer> runningTotals(ArrayList<Integer> nums) {
        ArrayList<Integer> result = new ArrayList<>();
        int total = 0;
        for (int value : nums) {
            total += value;
            result.add(total);
        }
        return result;
    }
}
